from pathlib import Path
import base64, zlib, json

DATA = ''
patch = zlib.decompress(base64.b64decode(DATA)).decode('utf-8')
patch_path = Path('payload/userscript-2.5.0.patch01.txt')
patch_path.write_text(patch, encoding='utf-8')

release_path = Path('release-userscript.json')
release = json.loads(release_path.read_text(encoding='utf-8'))
release['version'] = '2.5.0'
parts = [p for p in release.get('parts', []) if p != 'payload/userscript-2.5.0.patch01.txt']
parts.append('payload/userscript-2.5.0.patch01.txt')
release['parts'] = parts
release['release_build'] = max(int(release.get('release_build', 0)) + 1, 27)
release_path.write_text(json.dumps(release, indent=2) + '\n', encoding='utf-8')
print('Wrote userscript v2.5.0 patch and release config.')
